import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";
import NodeID3 from "npm:node-id3";
import { Buffer } from "node:buffer";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

const safeFileName = (name: string) => name.replace(/[^a-zA-Z0-9._-]/g, "_").slice(-180) || "soubor";

Deno.serve(async (request) => {
  if (request.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  if (request.method !== "POST") return new Response(JSON.stringify({ error: "Použij POST požadavek." }), { status: 405, headers: { ...corsHeaders, "Content-Type": "application/json" } });

  const authorization = request.headers.get("Authorization");
  if (!authorization) return new Response(JSON.stringify({ error: "Chybí přihlášení." }), { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } });

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const supabasePublishableKey = Deno.env.get("SUPABASE_ANON_KEY");
  if (!supabaseUrl || !supabasePublishableKey) return new Response(JSON.stringify({ error: "Externí cloud není správně nakonfigurován." }), { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } });

  const supabase = createClient(supabaseUrl, supabasePublishableKey, { global: { headers: { Authorization: authorization } } });
  const { data: { user }, error: userError } = await supabase.auth.getUser();
  if (userError || !user) return new Response(JSON.stringify({ error: "Neplatné přihlášení." }), { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } });

  const input = await request.json().catch(() => null) as { action?: string; versionId?: string; label?: string; note?: string | null } | null;
  if (input?.action === "health") return new Response(JSON.stringify({ ok: true, service: "songcraft-media", owner: user.id }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
  if (input?.action !== "prepare_tagged_copy" || !input.versionId || !input.label?.trim()) return new Response(JSON.stringify({ error: "Neplatný požadavek na přípravu MP3 kopie." }), { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } });

  const { data: version, error: versionError } = await supabase.from("sc_audio_versions").select("*").eq("id", input.versionId).single();
  if (versionError || !version) return new Response(JSON.stringify({ error: "Zvuková verze nebyla nalezena." }), { status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" } });
  const { data: song, error: songError } = await supabase.from("sc_songs").select("*").eq("id", version.song_id).single();
  if (songError || !song) return new Response(JSON.stringify({ error: "Skladba pro zvukovou verzi nebyla nalezena." }), { status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" } });

  const { data: album } = song.album_id ? await supabase.from("sc_albums").select("name, cover_path").eq("id", song.album_id).maybeSingle() : { data: null };
  const { data: sourceBlob, error: sourceError } = await supabase.storage.from("songcraft").download(version.storage_path);
  if (sourceError || !sourceBlob) return new Response(JSON.stringify({ error: "Původní MP3 se nepodařilo načíst." }), { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } });

  const coverPath = song.cover_path || album?.cover_path;
  let image: { mime: string; type: { id: number }; description: string; imageBuffer: Buffer } | undefined;
  if (coverPath) {
    const { data: coverBlob } = await supabase.storage.from("songcraft").download(coverPath);
    if (coverBlob) image = { mime: coverBlob.type || "image/jpeg", type: { id: 3 }, description: "SongCraft cover", imageBuffer: Buffer.from(await coverBlob.arrayBuffer()) };
  }

  const source = Buffer.from(await sourceBlob.arrayBuffer());
  const tagged = NodeID3.update({ title: song.title, artist: "Temney", performerInfo: "Temney", album: album?.name || version.id3_album || "", trackNumber: version.id3_track_number || undefined, year: version.id3_year || undefined, genre: version.id3_genre || undefined, comment: input.note ? { language: "eng", text: input.note } : version.id3_comment ? { language: "eng", text: version.id3_comment } : undefined, image }, source);
  if (!(tagged instanceof Buffer)) return new Response(JSON.stringify({ error: "ID3 tagy se nepodařilo vložit do MP3." }), { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } });

  const finalName = `${safeFileName(`Temney - ${song.title}${album?.name ? ` - ${album.name}` : ""} - ${input.label.trim()}`).replace(/\.mp3$/i, "")}.mp3`;
  const targetPath = `${user.id}/audio/managed/${finalName}`;
  const { error: uploadError } = await supabase.storage.from("songcraft").upload(targetPath, tagged, { contentType: "audio/mpeg", upsert: true });
  if (uploadError) return new Response(JSON.stringify({ error: "Hotovou MP3 kopii se nepodařilo uložit." }), { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } });

  const { error: updateError } = await supabase.from("sc_audio_versions").update({ label: input.label.trim(), original_file_name: finalName, storage_path: targetPath, tagged_storage_path: targetPath, id3_title: song.title, id3_artist: "Temney", id3_album: album?.name || null, id3_comment: input.note || version.id3_comment, updated_at: new Date().toISOString() }).eq("id", version.id);
  if (updateError) return new Response(JSON.stringify({ error: "Hotovou MP3 se sice podařilo uložit, ale nepodařilo se aktualizovat metadata." }), { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } });

  return new Response(JSON.stringify({ path: targetPath, fileName: finalName }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
});
